USE QuanLyThucDon;
GO
SET XACT_ABORT ON;
BEGIN TRY
BEGIN TRANSACTION;
IF OBJECT_ID(N'dbo.NguonDinhDuongChiSo',N'U') IS NULL CREATE TABLE dbo.NguonDinhDuongChiSo (MaNguyenLieu nvarchar(20) NOT NULL,ChiSo nvarchar(40) NOT NULL,GiaTri decimal(10,2) NOT NULL,Nguon nvarchar(2048) NOT NULL,MaThucPham nvarchar(50) NOT NULL,GhiChu nvarchar(max) NOT NULL,GiaTriTruoc decimal(10,2) NULL,NgayDoiChieu datetime2 NOT NULL,CONSTRAINT PK_NguonDinhDuongChiSo PRIMARY KEY(MaNguyenLieu,ChiSo));
-- NL017 Sườn heo: presumed zero, not analytical measurement.
IF NOT EXISTS(SELECT 1 FROM dbo.NguyenLieu WHERE MaNguyenLieu=N'NL017' AND TenNguyenLieu=N'Sườn heo') THROW 51200,N'Tên/mã nguyên liệu đã thay đổi.',1;
IF (SELECT COUNT(*) FROM dbo.ThongTinDinhDuong WITH(UPDLOCK,HOLDLOCK) WHERE MaNguyenLieu=N'NL017')<>1 OR NOT EXISTS(SELECT 1 FROM dbo.ThongTinDinhDuong WHERE MaNguyenLieu=N'NL017' AND MaThongTin=N'DD017' AND KhoiLuongChuan=100 AND MaDonVi=N'DVT001' AND (ChatXo IS NULL OR ChatXo=0)) THROW 51201,N'Hồ sơ/đơn vị/chất xơ đã đổi. Dừng cập nhật.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.NguonDinhDuongChiSo WHERE MaNguyenLieu=N'NL017' AND ChiSo=N'ChatXo') INSERT dbo.NguonDinhDuongChiSo VALUES(N'NL017',N'ChatXo',0,N'https://www.fao.org/fileadmin/templates/food_composition/documents/Guidelines_data_checking_02.pdf',N'FAO-PRESUMED-ZERO',N'PRESUMED_ZERO theo FAO/INFOODS 2012: chất xơ bằng 0 ở thực phẩm động vật tự nhiên không pha nguyên liệu khác (trừ côn trùng). Đây là suy định sinh học có nguồn, KHÔNG phải số xét nghiệm của mẫu. Chỉ bổ sung ChatXo; không xác minh lại kcal, natri, các chất khác hoặc tỷ lệ xương/vỏ.',NULL,SYSUTCDATETIME());
UPDATE dbo.NguonDinhDuongChiSo SET GiaTri=0,Nguon=N'https://www.fao.org/fileadmin/templates/food_composition/documents/Guidelines_data_checking_02.pdf',MaThucPham=N'FAO-PRESUMED-ZERO',GhiChu=N'PRESUMED_ZERO theo FAO/INFOODS 2012: chất xơ bằng 0 ở thực phẩm động vật tự nhiên không pha nguyên liệu khác (trừ côn trùng). Đây là suy định sinh học có nguồn, KHÔNG phải số xét nghiệm của mẫu. Chỉ bổ sung ChatXo; không xác minh lại kcal, natri, các chất khác hoặc tỷ lệ xương/vỏ.',NgayDoiChieu=SYSUTCDATETIME() WHERE MaNguyenLieu=N'NL017' AND ChiSo=N'ChatXo';
UPDATE dbo.ThongTinDinhDuong SET ChatXo=0 WHERE MaNguyenLieu=N'NL017';
